-- Live table shapes (2026-11-17 snapshot), studio tables only.
create table public.studio_assets (id uuid default gen_random_uuid() primary key, user_id uuid not null references auth.users(id), task_id text not null, file_name text not null default 'x.png', original_name text, mime_type text not null default 'image/png', declared_mime text, size_bytes integer not null default 1, width integer, height integer, sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'), path text not null unique default gen_random_uuid()::text, source text not null default 'base64', note text, created_at timestamptz default now() not null);
create table public.studio_tasks (id uuid default gen_random_uuid() primary key, user_id uuid not null references auth.users(id), project text not null, title text not null, brief text not null, status text default 'open' not null check (status in ('open','blocked','done')), turn text check (turn in ('claude','chatgpt','kody')), created_by text not null check (created_by in ('claude','chatgpt','kody')), refs jsonb default '[]' not null, version integer default 1 not null, request_key text not null, created_at timestamptz default now() not null, updated_at timestamptz default now() not null, unique (user_id, request_key));
create table public.studio_messages (id bigserial primary key, task_id uuid not null references public.studio_tasks(id) on delete cascade, user_id uuid not null, seq integer not null, author text not null check (author in ('claude','chatgpt','kody')), kind text not null check (kind in ('note','review','question','decision','report')), body text not null, refs jsonb default '[]' not null, set_status text check (set_status in ('open','blocked','done')), set_turn text check (set_turn in ('claude','chatgpt','kody')), request_key text not null, created_at timestamptz default now() not null, unique (task_id, seq), unique (user_id, request_key));
create table public.studio_worker_runs (id bigserial primary key, task_id uuid not null references public.studio_tasks(id) on delete cascade, user_id uuid not null, task_version integer not null, status text default 'started' not null, detail text, created_at timestamptz default now() not null, finished_at timestamptz, step text, heartbeat_at timestamptz, plan jsonb, done_assets jsonb default '[]' not null, next_part integer default 0 not null, part_started_at timestamptz, resumes integer default 0 not null, alerted boolean default false not null, error_kind text, unique (task_id, task_version));
create table public.studio_run_events (id bigserial primary key, task_id uuid not null references public.studio_tasks(id) on delete cascade, user_id uuid not null, run_id bigint, task_version integer, actor text not null, kind text not null, detail text, request_id bigint, at timestamptz default now() not null);
create table public.studio_claude_wakes (id bigserial primary key, task_id uuid not null, request_id bigint, created_at timestamptz default now() not null, task_version integer);
create table public.studio_push_subs (endpoint text primary key, user_id uuid not null, sub jsonb not null, created_at timestamptz default now() not null);
create table public.studio_stuck_alerts (task_id uuid not null, task_version integer not null, created_at timestamptz default now() not null, primary key (task_id, task_version));
